 = $__env->getLastLoop(); ?> <?php else: ?> <?php $__currentLoopData = $orders; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $order): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option data-entity="<?php echo e($order->customer_id); ?>" data-due="<?php echo e($order->total); ?>"><?php echo e($order->order_number); ?> — Due BDT <?php echo e(number_format($order->total,2)); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?> <?php endif; ?></select></div><div class="col-md-4"><label class="form-label">Due amount</label><input id="due" class="form-control" readonly value="0.00"></div><div class="col-md-4"><label class="form-label">Payment type</label><select name="payment_method_id" class="form-select" required><?php $__currentLoopData = $methods; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $method): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($method->id); ?>"><?php echo e($method->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><div class="col-md-4"><label class="form-label">Amount</label><input id="amount" name="amount" type="number" min=".01" step=".01" class="form-control" required></div></div><button class="btn text-white mt-4" style="background:var(--brand)">Save</button></form><script>const e=document.querySelector('#entity'),v=document.querySelector('#voucher'),d=document.querySelector('#due'),a=document.querySelector('#amount');const filter=()=>{[...v.options].forEach(o=>o.hidden=!!o.dataset.entity&&o.dataset.entity!==e.value);v.value='';d.value='0.00'};e.onchange=filter;v.onchange=()=>{d.value=v.selectedOptions[0]?.dataset.due||'0.00';a.max=d.value;a.value=d.value};filter();</script>
